	('cfbfe9e7-6642-415f-a7b9-ffb8ced7fee7', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'INC-2026-000001', 'Active Malware Infection - Jebel Ali', 'Unauthorized malware detected on HMI workstations at Jebel Ali Grid Station targeting SCADA protocols.', 'malware-infection', 'critical', 'p1-critical', 'investigating', 'fd159233-57ce-4300-99b5-22a04155a53b', NULL, 'ffb10062-9448-4e54-b354-f0f3e16e33bf', '{6f415f6b-cb50-4da2-85d8-1025d6f9c119}', '{}', '{}', '{}', '2026-02-13 05:06:05.358585+00', '2026-02-13 06:06:05.358585+00', NULL, NULL, NULL, NULL, '{}', 'High potential for operational disruption and unauthorized grid control.', 150000.00, 0, 0, NULL, NULL, NULL, NULL, '{"Isolate affected workstations","Block command and control IP addresses"}', '{"Run full antivirus scan","Reimage infected workstations from known-good backups"}', '{"Restore system operations","Verify integrity of SCADA configurations"}', 'Initial assessment suggests entry via infected USB drive during maintenance.', NULL, NULL, '[]', NULL, NULL, NULL, false, NULL, '{}', '{}', '2026-02-13 09:06:05.358585+00', '2026-02-13 09:06:05.358585+00'),
	('b7f13399-fca2-4bc0-9ad6-be099f01e2f7', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'INC-2026-000002', 'Unauthorized Access Attempt - Dubai Main', 'Multiple failed login attempts detected on the main gateway from a suspicious external IP address.', 'unauthorized-access', 'high', 'p2-high', 'contained', 'ffb10062-9448-4e54-b354-f0f3e16e33bf', NULL, 'fd159233-57ce-4300-99b5-22a04155a53b', '{ea3fb3ce-4437-4983-8c2b-fec72a1775d6}', '{}', '{}', '{}', '2026-02-12 09:06:05.358585+00', '2026-02-12 10:06:05.358585+00', NULL, NULL, NULL, NULL, '{}', 'Potential for unauthorized access to the internal network and sensitive grid data.', 50000.00, 0, 0, NULL, NULL, NULL, NULL, '{"Block malicious IP address at firewall","Reset credentials for targeted accounts"}', '{"Audit logs for successful logins from suspicious IP","Verify two-factor authentication configuration"}', '{"Monitor for further access attempts","Implement geo-fencing for administrative access"}', 'Successful containment within 30 minutes of detection.', NULL, NULL, '[]', NULL, NULL, NULL, false, NULL, '{}', '{}', '2026-02-13 09:06:05.358585+00', '2026-02-13 09:06:05.358585+00'),
	('1ee742ba-729e-43f8-965a-0b1e7cfc9e97', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'INC-2026-000003', 'Unauthorized Physical Access', 'Security breach detected at Al Aweer Regional Hub. Unauthorized personnel gained access to control room.', 'physical-security', 'medium', 'p3-medium', 'resolved', '2e4ba450-22f8-42d5-b89c-3e497829289b', NULL, '2b95d280-9ec0-4aa1-b1d3-6bb4b13f82de', '{87a51493-079a-4d9a-a3f9-fb06b16ba596}', '{}', '{}', '{}', '2026-02-11 09:06:05.358585+00', '2026-02-11 10:06:05.358585+00', NULL, NULL, NULL, NULL, '{}', 'Low - No system compromise detected', 15000.00, 0, 0, NULL, NULL, NULL, NULL, '{"Enhanced physical security measures","Reviewed access logs","Updated badge access controls"}', NULL, NULL, 'Physical security protocols need regular review and testing', NULL, NULL, '[]', NULL, NULL, NULL, false, NULL, '{}', '{}', '2026-02-13 09:06:05.358585+00', '2026-02-13 09:06:05.358585+00'),
	('47eb376c-28a7-4543-b859-9f2ff6c73086', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'INC-2026-000004', 'Network Intrusion Attempt', 'Multiple failed network intrusion attempts detected across transmission network infrastructure.', 'unauthorized-access', 'high', 'p2-high', 'open', '2b95d280-9ec0-4aa1-b1d3-6bb4b13f82de', NULL, '2e4ba450-22f8-42d5-b89c-3e497829289b', '{ea3fb3ce-4437-4983-8c2b-fec72a1775d6,6f415f6b-cb50-4da2-85d8-1025d6f9c119}', '{}', '{}', '{}', '2026-02-10 09:06:05.358585+00', '2026-02-10 10:06:05.358585+00', NULL, NULL, NULL, NULL, '{}', 'Medium - Network security at risk', 50000.00, 0, 0, NULL, NULL, NULL, NULL, '{"Strengthened firewall rules","Implemented additional monitoring"}', NULL, NULL, 'Ongoing monitoring for suspicious network activity.', NULL, NULL, '[]', NULL, NULL, NULL, false, NULL, '{}', '{}', '2026-02-13 09:06:05.358585+00', '2026-02-13 09:06:05.358585+00'),
	('6c78d230-a6d2-4797-83fb-832cb41e1748', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'INC-2026-000005', 'Power Grid Oscillation Anomaly', 'Unexplained power oscillations detected across multiple transmission sites suggesting potential synchronized manipulation.', 'system-compromise', 'high', 'p2-high', 'open', NULL, NULL, 'fd159233-57ce-4300-99b5-22a04155a53b', '{6f415f6b-cb50-4da2-85d8-1025d6f9c119,ea3fb3ce-4437-4983-8c2b-fec72a1775d6}', '{}', '{}', '{}', '2026-02-13 07:06:05.358585+00', '2026-02-13 08:06:05.358585+00', NULL, NULL, NULL, NULL, '{}', 'Critical threat to grid stability and equipment lifespan.', 120000.00, 0, 0, NULL, NULL, NULL, NULL, '{"Enable high-speed telemetry recording","Increase sampling frequency on protection relays"}', NULL, NULL, 'Investigation ongoing into potential wide-area network compromise.', NULL, NULL, '[]', NULL, NULL, NULL, false, NULL, '{}', '{}', '2026-02-13 09:06:05.358585+00', '2026-02-13 09:06:05.358585+00');
