	('b45bb933-8abd-4978-9a04-695664db5a0f', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'NERC CIP', 'Critical Infrastructure Protection Standards', 'Version 5', 'cybersecurity', 'compliant', 0.00, 0, 0, 0, 0, 0, '2023-11-20 14:30:00+00', NULL, '2024-05-20 14:30:00+00', 6, NULL, '{substation-control,scada-network,corporate-network}', true, 'North American Electric Reliability Corporation Critical Infrastructure Protection standards for bulk electric system cybersecurity, covering transmission substations and control centers.', 'NERC (North American Electric Reliability Corporation)', 'https://www.nerc.com/pa/Stand/Pages/CIPStandards.aspx', '{https://www.nerc.com/pa/Stand/Reliability%20Standards/CIP-002-5.1.pdf,https://www.nerc.com/pa/Stand/Reliability%20Standards/CIP-007-6.pdf}', 'Mandatory for bulk electric system assets including transmission substations above 100kV', '2026-02-13 09:06:05.293386+00', '2026-02-13 09:06:05.293386+00'),
	('439a8819-31d0-4fb9-b6b1-6786dfca9234', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'IEEE 1686', 'Standard for Intelligent Electronic Devices Cyber Security Capabilities', '2013', 'cybersecurity', 'in-progress', 0.00, 0, 0, 0, 0, 0, '2024-02-10 09:15:00+00', NULL, '2024-08-10 09:15:00+00', 12, NULL, '{substation-control,protection-systems,field-devices}', true, 'IEEE standard defining cyber security capabilities for intelligent electronic devices used in electric power systems, particularly protection relays and substation automation systems.', 'IEEE (Institute of Electrical and Electronics Engineers)', 'https://standards.ieee.org/ieee/1686/5266/', '{https://ieeexplore.ieee.org/document/6679950}', 'Focused on protection relays, meters, and other intelligent electronic devices in transmission substations', '2026-02-13 09:06:05.293386+00', '2026-02-13 09:06:05.293386+00'),
	('c6ba5784-cdcb-4300-a5d5-1474d69e215a', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'ISO 27001', 'Information Security Management Systems', '2022', 'cybersecurity', 'in-progress', 0.00, 0, 0, 0, 0, 0, '2023-12-05 16:45:00+00', NULL, '2024-06-05 16:45:00+00', 12, NULL, '{scada-network,corporate-network,maintenance-network}', false, 'International standard for information security management systems, applied to power transmission operations including SCADA networks, control centers, and corporate IT systems.', 'ISO (International Organization for Standardization)', 'https://www.iso.org/isoiec-27001-information-security.html', '{https://www.iso.org/standard/27001,https://www.iso.org/standard/75652.html}', 'Comprehensive information security framework covering all aspects of transmission system cybersecurity', '2026-02-13 09:06:05.293386+00', '2026-02-13 09:06:05.293386+00'),
	('485368a5-8626-44de-85a2-762de93c2825', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'NIST CSF', 'Cybersecurity Framework for Critical Infrastructure', '2.0', 'cybersecurity', 'in-progress', 0.00, 0, 0, 0, 0, 0, '2024-01-30 11:20:00+00', NULL, '2024-07-30 11:20:00+00', 12, NULL, '{substation-control,protection-systems,scada-network,corporate-network}', false, 'NIST Cybersecurity Framework providing a policy framework of computer security guidance for critical infrastructure sectors including electric power transmission.', 'NIST (National Institute of Standards and Technology)', 'https://www.nist.gov/cyberframework', '{https://nvlpubs.nist.gov/nistpubs/CSWP/NIST.CSWP.04162018.pdf,https://www.nist.gov/cyberframework/framework}', 'Voluntary framework widely adopted by electric utilities for cybersecurity risk management', '2026-02-13 09:06:05.293386+00', '2026-02-13 09:06:05.293386+00'),
	('a5970477-9458-4791-bb64-829b5c488e7d', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'IEC 62443', 'Industrial Automation and Control Systems Security', '2018', 'cybersecurity', 'non-compliant', 58.33, 3, 1, 1, 1, 0, '2024-01-15 10:00:00+00', NULL, '2024-07-15 10:00:00+00', 12, NULL, '{substation-control,protection-systems,scada-network,field-devices}', true, 'International standard for cybersecurity of industrial automation and control systems, specifically applied to power transmission infrastructure including substations, SCADA systems, and protection relays.', 'IEC (International Electrotechnical Commission)', 'https://www.iec.ch/dyn/www/f?p=103:23:0::::FSP_ORG_ID:1316', '{https://webstore.iec.ch/publication/33615,https://www.iec.ch/cyber-security}', 'Applied specifically to power transmission infrastructure with focus on IEC 61850 communications and protection systems', '2026-02-13 09:06:05.293386+00', '2026-02-13 09:06:05.293386+00');
INSERT INTO "public"."compliance_requirements" ("id", "tenant_id", "standard_id", "requirement_id", "requirement_name", "requirement_description", "requirement_section", "status", "implementation_percentage", "priority", "risk_if_not_met", "implementation_approach", "responsible_party", "target_completion_date", "actual_completion_date", "evidence_required", "evidence_provided", "validation_method", "last_validated", "validated_by", "gap_description", "remediation_plan", "remediation_status", "related_controls", "notes", "created_at", "updated_at") VALUES
	('7814a619-ab12-4f4f-8c81-ad0f13fbebcc', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'a5970477-9458-4791-bb64-829b5c488e7d', 'IEC-62443-3-3-SR-1.1', 'Identification and Authentication Control', 'The control system shall provide the capability to identify and authenticate all users (humans, software processes, or devices) before allowing access to the control system.', '3-3 SR 1.1', 'compliant', 100.00, 'critical', 'critical', 'Multi-factor authentication implemented for all transmission SCADA systems and protection relay access', 'Cybersecurity Team', '2023-12-31 23:59:59+00', NULL, '{"MFA configuration documentation","User access logs","Authentication policy"}', '{"MFA deployment guide","Access control matrix","Authentication audit logs"}', 'Automated testing and manual review', '2024-01-15 10:00:00+00', 'Security Auditor', NULL, NULL, 'completed', NULL, 'Successfully implemented across all transmission substations', '2026-02-13 09:06:05.293386+00', '2026-02-13 09:06:05.293386+00'),
	('6fe473d0-3ab2-460f-93eb-e587a8fcf5c1', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'a5970477-9458-4791-bb64-829b5c488e7d', 'IEC-62443-3-3-SR-2.1', 'Authorization Enforcement', 'The control system shall enforce approved authorizations for logical access to information and system resources.', '3-3 SR 2.1', 'in-progress', 75.00, 'high', 'high', 'Role-based access control implementation for transmission operations', 'Operations Team', '2024-06-30 23:59:59+00', NULL, '{"RBAC policy document","Role definitions","Access approval workflows"}', '{"Draft RBAC policy","Preliminary role matrix"}', 'Policy review and access testing', NULL, NULL, 'Need to complete role definitions for maintenance personnel', 'Finalize maintenance role definitions and implement approval workflows', 'in-progress', NULL, 'Phase 1 complete for operators and engineers, Phase 2 pending for maintenance roles', '2026-02-13 09:06:05.293386+00', '2026-02-13 09:06:05.293386+00'),
	('4ffc196a-b2fc-459b-954d-ced748b5cbfb', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'a5970477-9458-4791-bb64-829b5c488e7d', 'IEC-62443-3-3-SR-3.1', 'Communication Integrity', 'The control system shall protect the integrity of transmitted information.', '3-3 SR 3.1', 'non-compliant', 25.00, 'critical', 'critical', 'Implement encryption for IEC 61850 GOOSE and MMS communications', 'Engineering Team', '2024-09-30 23:59:59+00', NULL, '{"Encryption implementation plan","IEC 61850 security configuration","Communication integrity tests"}', '{"Initial security assessment"}', 'Communication protocol analysis and penetration testing', NULL, NULL, 'IEC 61850 communications not encrypted, GOOSE messages in plaintext', 'Deploy IEC 62351 security extensions for encrypted communications', 'not-started', NULL, 'Critical gap requiring immediate attention for transmission protection systems', '2026-02-13 09:06:05.293386+00', '2026-02-13 09:06:05.293386+00');
