	('0a397ac6-d29e-4f3a-b435-f309b974619c', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', NULL, 'Q4 2023 DEWA Cybersecurity Risk & Compliance Summary', '2026-02-03 09:06:05.182626+00', '2023-10-01 00:00:00+00', '2023-12-31 00:00:00+00', 'quarterly', 45, 3, 12, 22, 8, 28, 5, 42.50, 68.00, 42.50, 50.00, false, 5, 3, 2, 0, 88.40, 88.24, 91.67, 300, 251, 36, 13, 86.75, 8, 1, 6, 127, 8, 850, 285, 45, 805, 'improving', 'stable', 'improving', 'DEWA demonstrated strong cybersecurity posture in Q4 2023 with 88.4% overall compliance score. Risk levels remain within acceptable thresholds. Three critical risks identified related to legacy system vulnerabilities, all with active mitigation plans.', '{"IEC 62443 compliance improved from 85% to 88.24% through enhanced network segmentation","NERC CIP compliance maintained at 91.67% with zero critical findings","Incident response time improved by 35% through automation","Vulnerability remediation rate increased to 92% for critical findings","Three critical cyber incidents successfully contained with no operational impact"}', '{"Accelerate legacy system modernization program to address remaining critical risks","Implement continuous monitoring for all critical assets","Enhance security awareness training for operational staff","Deploy advanced threat detection capabilities for EMS and SCADA systems","Establish formal vendor security assessment program"}', '{"Complete MFA deployment for all privileged accounts by Q1 2024","Conduct penetration testing of control centre systems","Update incident response playbooks for transmission-specific scenarios","Implement automated vulnerability scanning for OT networks"}', 'approved', 'Saeed Al Tayer', '2026-02-08 09:06:05.182626+00', 'Quarterly executive summary presented to board. All action items tracked in project management system.', '2026-02-03 09:06:05.182626+00', '2026-02-08 09:06:05.182626+00'),
	('19b335b2-72d9-49d6-9b9f-720128a55616', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '6f415f6b-cb50-4da2-85d8-1025d6f9c119', 'January 2024 Jebel Ali Security Summary', '2026-02-08 09:06:05.182626+00', '2024-01-01 00:00:00+00', '2024-01-31 00:00:00+00', 'monthly', 18, 2, 5, 9, 2, 12, 2, 38.75, 62.00, 38.75, 45.00, false, 3, 2, 1, 0, 87.50, 88.24, 0.00, 85, 68, 12, 5, 85.50, 3, 1, 2, 42, 3, 285, 95, 12, 273, 'stable', 'improving', 'stable', 'Jebel Ali Power Station maintained strong security posture in January 2024. One critical incident (coordinated cyber attack) was successfully contained. Security controls effectiveness at 85.5%.', '{"Successfully defended against coordinated cyber attack targeting turbine control systems","Completed quarterly vulnerability assessment with 92% remediation rate","Enhanced monitoring detected 3 unauthorized access attempts, all blocked","Patch compliance improved to 94% for critical systems"}', '{"Implement additional network segmentation for process control zone","Deploy behavioral analytics for anomaly detection","Enhance physical security integration with cyber monitoring"}', '{"Complete network segmentation project by end of Q1","Deploy endpoint detection and response (EDR) on all HMI workstations","Conduct tabletop exercise for cyber incident response"}', 'approved', 'Ahmed Al Mansouri', '2026-02-11 09:06:05.182626+00', 'Monthly site security review. Incident response effectiveness validated.', '2026-02-08 09:06:05.182626+00', '2026-02-11 09:06:05.182626+00'),
