	('1fbfefb0-9398-48a7-bd6c-ee5cfee6f449', '0a397ac6-d29e-4f3a-b435-f309b974619c', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'NERC CIP Version 6', 'v6', 'nerc-cip', 'compliant', 91.67, 120, 105, 10, 5, '2026-01-14 09:06:05.182626+00', '2026-08-12 09:06:05.182626+00', 'Mohammed bin Rashid', 0, 2, 'Full compliance with NERC CIP critical infrastructure protection requirements. Minor documentation gaps.', 'Complete training documentation updates. Enhance incident response drill frequency.', 'Covers all BES Cyber Systems and associated Electronic Security Perimeters.', '2026-02-03 09:06:05.182626+00', '2026-02-03 09:06:05.182626+00'),
	('4a473f00-f94b-4814-8da5-aade54d81179', '0a397ac6-d29e-4f3a-b435-f309b974619c', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'UAE Federal Decree-Law No. 5 of 2012', '2023', 'other', 'compliant', 92.00, 50, 45, 4, 1, '2025-12-15 09:06:05.182626+00', '2027-02-13 09:06:05.182626+00', 'Mohammed bin Rashid', 0, 1, 'Strong compliance with UAE Cybersecurity Law requirements for critical infrastructure. One high-priority gap in data localization.', 'Complete data residency assessment. Implement data classification framework.', 'Annual compliance review conducted by UAE Cyber Security Council.', '2026-02-03 09:06:05.182626+00', '2026-02-03 09:06:05.182626+00');
