INSERT INTO "public"."control_coverage_assessments" ("id", "tenant_id", "site_id", "assessment_name", "assessment_date", "assessor", "assessment_type", "standard_name", "standard_version", "total_controls", "implemented_controls", "partial_controls", "not_implemented_controls", "not_applicable_controls", "coverage_score", "effectiveness_score", "maturity_level", "status", "compliance_status", "critical_gaps", "high_gaps", "medium_gaps", "low_gaps", "gap_summary", "remediation_plan", "target_completion_date", "next_assessment_date", "notes", "created_at", "updated_at") VALUES
	('96400620-7b0c-401a-b786-73f3eca6a7c7', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '6f415f6b-cb50-4da2-85d8-1025d6f9c119', 'IEC 62443-3-3 Security Level 2 Assessment - Jebel Ali', '2025-12-30 09:06:05.182626+00', 'Fatima Al Zahra', 'iec-62443', 'IEC 62443-3-3', '2013', 85, 68, 12, 5, 0, 88.24, 85.50, 2, 'completed', 'partial', 2, 3, 8, 4, 'Overall strong security posture with some gaps in network segmentation and access control. Critical gaps identified in remote access monitoring and encryption key management.', 'Implement enhanced network segmentation for process control zone. Deploy MFA for all privileged access. Upgrade encryption protocols to AES-256.', '2026-05-14 09:06:05.182626+00', '2027-02-13 09:06:05.182626+00', 'Assessment conducted during planned maintenance window. All critical systems reviewed.', '2025-12-30 09:06:05.182626+00', '2025-12-30 09:06:05.182626+00'),
	('5e694d58-b273-4b57-9c3c-8e5e255c9b47', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'ea3fb3ce-4437-4983-8c2b-fec72a1775d6', 'NERC CIP Compliance Assessment - Control Centre', '2026-01-14 09:06:05.182626+00', 'Mohammed bin Rashid', 'nerc-cip', 'NERC CIP Version 6', 'v6', 120, 105, 10, 5, 0, 91.67, 88.00, 3, 'completed', 'compliant', 0, 2, 5, 3, 'Strong compliance with NERC CIP requirements. Minor gaps in personnel training documentation and incident response testing frequency.', 'Complete quarterly incident response drills. Update training records for all operators. Enhance logging for CIP-007 compliance.', '2026-04-14 09:06:05.182626+00', '2026-08-12 09:06:05.182626+00', 'Annual compliance assessment. All BES Cyber Systems reviewed and documented.', '2026-01-14 09:06:05.182626+00', '2026-01-14 09:06:05.182626+00'),
	('95176424-decc-44ef-9fbe-e46eca8ae71b', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '87a51493-079a-4d9a-a3f9-fb06b16ba596', 'Combined IEC 62443 & UAE Cybersecurity Assessment', '2026-01-29 09:06:05.182626+00', 'Ahmed Al Mansouri', 'combined', 'IEC 62443 + UAE Cyber Law', '2023', 5, 3, 1, 1, 0, 70.00, 70.00, 2, 'in-progress', 'partial', 0, 1, 1, 0, 'Good overall security posture. Critical gap in backup system testing. High priority gaps in vulnerability management and patch deployment processes.', 'Implement automated vulnerability scanning. Establish monthly backup restoration testing. Deploy centralized patch management system.', '2026-06-13 09:06:05.182626+00', '2027-02-13 09:06:05.182626+00', 'Assessment in progress. Final report expected within 2 weeks.', '2026-01-29 09:06:05.182626+00', '2026-02-13 09:06:05.182626+00'),
