INSERT INTO "public"."security_policies" ("id", "tenant_id", "policy_id", "policy_name", "policy_description", "policy_type", "version", "version_date", "previous_version_id", "superseded_by_id", "status", "effective_date", "review_date", "expiration_date", "review_frequency_months", "scope", "enforcement_level", "applies_to_sites", "applies_to_zones", "applies_to_roles", "applies_to_asset_types", "policy_statement", "purpose", "objectives", "requirements", "procedures", "exceptions_allowed", "exception_criteria", "related_standards", "related_controls", "regulatory_requirements", "created_by", "reviewed_by", "approved_by", "review_date_actual", "approval_date", "approval_notes", "policy_owner", "policy_owner_role", "responsible_parties", "document_url", "document_version", "related_documents", "training_required", "training_materials", "compliance_mandatory", "compliance_tracking_enabled", "last_compliance_check", "compliance_rate", "tags", "notes", "created_at", "updated_at") VALUES
	('e1922966-9dbe-4529-a546-1cceaa58242b', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-TRANS-DP-001', 'Transmission System Data Protection Policy', 'Establishes data protection and privacy requirements for transmission system operational data, including SCADA data, protection settings, and system configurations.', 'Data Protection', '1.2', '2023-10-01 00:00:00+00', NULL, NULL, 'active', '2023-10-01 00:00:00+00', '2024-04-01 00:00:00+00', '2024-10-01 00:00:00+00', 12, 'transmission', 'mandatory', NULL, '{scada-network,substation-control,corporate-network}', '{data-custodian,system-administrator,operations-analyst}', '{databases,historians,backup-systems,archive-systems}', 'All transmission system data must be classified, protected, and managed according to its sensitivity and criticality to ensure confidentiality, integrity, and availability.', 'To protect sensitive transmission system data from unauthorized access, modification, or disclosure while ensuring availability for operational needs.', '{"Classify all transmission system data based on sensitivity and criticality","Implement appropriate protection measures for each data classification","Ensure secure data backup and recovery capabilities","Maintain data retention and disposal procedures","Monitor data access and usage patterns"}', '{"All data must be classified as Public, Internal, Confidential, or Restricted","Confidential and Restricted data must be encrypted at rest and in transit","Data access must be logged and monitored continuously","Backup data must be tested and verified regularly","Data retention periods must comply with regulatory requirements","Secure data disposal procedures must be followed","Data sharing agreements must be established for external parties"}', 'Data protection procedures are detailed in the Data Classification and Handling Guide. Data custodians are responsible for implementing appropriate protection measures.', true, 'Temporary data access may be granted for emergency operations, subject to immediate logging and subsequent review within 24 hours.', '{c6ba5784-cdcb-4300-a5d5-1474d69e215a}', '{}', '{"ISO 27001 A.8.2.1","ISO 27001 A.8.2.3","NERC CIP-011-2"}', 'cf6713ee-aab0-4d03-878a-3f46d440f014', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2023-09-25 13:00:00+00', '2023-09-28 17:00:00+00', 'Policy approved with clarifications on data classification criteria', 'Data Protection Officer', 'Data Protection Officer', '{"Data Custodians","System Administrators","Database Administrators"}', 'https://policies.dewa.gov.ae/transmission/data-protection-v1.2.pdf', '1.2', '{"Data Classification Guide","Encryption Standards","Backup and Recovery Procedures"}', true, '{"Data Classification Training","Encryption Implementation","Privacy Awareness"}', true, true, '2024-01-08 12:00:00+00', 91.80, '{data-protection,privacy,classification,encryption}', 'Updated to include enhanced encryption requirements and data sharing protocols', '2026-02-13 09:06:05.51224+00', '2026-02-13 09:06:05.51224+00'),
	('876e949a-3646-4d16-8cdc-d6a72db17cc7', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-TRANS-AC-001', 'Transmission System Access Control Policy', 'Defines access control requirements for all transmission system components including SCADA, protection relays, and substation automation systems.', 'Access Control', '2.1', '2024-01-01 00:00:00+00', NULL, NULL, 'active', '2024-01-01 00:00:00+00', '2024-07-01 00:00:00+00', '2025-01-01 00:00:00+00', 12, 'transmission', 'mandatory', NULL, '{substation-control,scada-network,protection-systems}', '{transmission-operator,protection-engineer,maintenance-technician,system-administrator}', '{scada-systems,protection-relays,hmi-workstations,substation-automation}', 'All access to transmission system components must be authenticated, authorized, and logged. Multi-factor authentication is required for all privileged access to critical systems.', 'To ensure secure and controlled access to transmission system components, protecting against unauthorized access that could compromise grid stability and safety.', '{"Implement strong authentication mechanisms for all system access","Enforce role-based access control based on job functions","Maintain comprehensive access logs and audit trails","Regularly review and update access permissions","Ensure segregation of duties for critical operations"}', '{"Multi-factor authentication required for all SCADA system access","Role-based access control must be implemented for all transmission systems","Access permissions must be reviewed quarterly","All access attempts must be logged and monitored","Privileged accounts must be managed through dedicated PAM system","Emergency access procedures must be documented and tested","Access must be revoked immediately upon role change or termination"}', 'Access control procedures are documented in the Transmission System Access Control Procedures manual. All access requests must be approved through the established workflow in the IT service management system.', true, 'Emergency access may be granted for critical system restoration activities, subject to immediate notification to the Security Manager and subsequent review within 24 hours.', '{a5970477-9458-4791-bb64-829b5c488e7d,b45bb933-8abd-4978-9a04-695664db5a0f}', '{91984d7d-9c8e-4de7-9a93-090792d59a89}', '{"NERC CIP-005-6","IEC 62443-3-3 SR 1.1","IEC 62443-3-3 SR 2.1"}', '4ba4b9a3-1ea1-413f-86bf-13565f150d35', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2023-12-15 10:00:00+00', '2023-12-20 14:00:00+00', 'Policy approved with minor revisions to emergency access procedures', 'Chief Information Security Officer', 'CISO', '{"Cybersecurity Team Lead","Operations Manager","Engineering Manager"}', 'https://policies.dewa.gov.ae/transmission/access-control-v2.1.pdf', '2.1', '{"Transmission System Security Standards","Emergency Response Procedures","User Access Management Guide"}', true, '{"Access Control Training Module","MFA Setup Guide","Role-Based Access Control Overview"}', true, true, '2026-02-13 09:06:05.51224+00', 100.00, '{access-control,authentication,authorization,critical}', 'Updated to include new MFA requirements and PAM system integration', '2026-02-13 09:06:05.51224+00', '2026-02-13 09:06:05.51224+00'),
	('83519ac0-41d0-4cea-924a-470e09aab586', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-TRANS-NS-001', 'Transmission Network Security Policy', 'Establishes network security requirements for transmission system communications including SCADA networks, protection system communications, and substation networks.', 'Network Security', '1.3', '2023-11-01 00:00:00+00', NULL, NULL, 'active', '2023-11-01 00:00:00+00', '2024-05-01 00:00:00+00', '2024-11-01 00:00:00+00', 12, 'transmission', 'mandatory', NULL, '{scada-network,substation-control,protection-systems}', '{network-engineer,cybersecurity-analyst,system-administrator}', '{network-equipment,firewalls,switches,communication-gateways}', 'All transmission system networks must be secured through network segmentation, encryption, and continuous monitoring. Critical communications must use approved secure protocols.', 'To protect transmission system networks from cyber threats and ensure the integrity and availability of critical communications.', '{"Implement network segmentation to isolate critical systems","Deploy encryption for sensitive communications","Establish continuous network monitoring and threat detection","Maintain network security baselines and configurations","Ensure secure remote access capabilities"}', '{"Network segmentation must separate SCADA, protection, and corporate networks","IEC 62351 security extensions must be implemented for IEC 61850 communications","All network devices must be hardened according to security standards","Network traffic must be monitored and analyzed for anomalies","Firewalls must be configured with deny-by-default rules","VPN access must use multi-factor authentication","Network configuration changes must be approved and documented"}', 'Network security procedures are detailed in the Network Security Implementation Guide. All network changes must follow the established change management process.', true, 'Temporary network configuration changes may be permitted for emergency restoration activities, subject to immediate security review and approval within 4 hours.', '{a5970477-9458-4791-bb64-829b5c488e7d,b45bb933-8abd-4978-9a04-695664db5a0f}', '{541c6477-296e-4135-8c13-b4ab3badc800}', '{"NERC CIP-005-6","IEC 62443-3-3 SR 3.1","IEC 62443-3-3 SR 4.1"}', 'ffb10062-9448-4e54-b354-f0f3e16e33bf', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2023-10-20 11:00:00+00', '2023-10-25 15:00:00+00', 'Policy approved with emphasis on IEC 62351 implementation timeline', 'Network Security Manager', 'Network Security Manager', '{"Network Engineering Team","Cybersecurity Team","Operations Team"}', 'https://policies.dewa.gov.ae/transmission/network-security-v1.3.pdf', '1.3', '{"Network Hardening Standards","IEC 62351 Implementation Guide","Network Monitoring Procedures"}', true, '{"Network Security Fundamentals","IEC 62351 Training","Firewall Management"}', true, true, '2026-02-13 09:06:05.51224+00', 100.00, '{network-security,encryption,monitoring,protocols}', 'Updated to include IEC 62351 requirements and enhanced monitoring capabilities', '2026-02-13 09:06:05.51224+00', '2026-02-13 09:06:05.51224+00'),
	('be9488f5-82e3-4818-8b98-9f9104279928', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-TRANS-IR-001', 'Transmission Cybersecurity Incident Response Policy', 'Defines incident response procedures for cybersecurity incidents affecting transmission system operations, including detection, response, recovery, and lessons learned.', 'Incident Response', '3.0', '2023-09-15 00:00:00+00', NULL, NULL, 'active', '2023-09-15 00:00:00+00', '2024-03-15 00:00:00+00', '2024-09-15 00:00:00+00', 12, 'transmission', 'mandatory', NULL, '{substation-control,scada-network,protection-systems,corporate-network}', '{incident-commander,security-analyst,operations-manager,engineering-manager}', '{scada-systems,protection-relays,control-centers,communication-systems}', 'All cybersecurity incidents affecting transmission systems must be promptly detected, reported, contained, and resolved following established procedures to minimize impact on grid operations.', 'To ensure rapid and effective response to cybersecurity incidents that could impact transmission system reliability, safety, and security.', '{"Establish 24/7 incident detection and response capabilities","Minimize incident impact on transmission system operations","Preserve evidence for forensic analysis and regulatory reporting","Coordinate response between IT, OT, and operations teams","Implement lessons learned to prevent future incidents"}', '{"Incidents must be detected and reported within 15 minutes of occurrence","Incident response team must be activated within 30 minutes","Initial containment actions must begin within 1 hour","Regulatory notifications must be made within required timeframes","All incidents must be documented and analyzed for lessons learned","Recovery procedures must prioritize safety and system stability","Post-incident reviews must be conducted within 72 hours"}', 'Detailed incident response procedures are documented in the Transmission Cyber Incident Response Plan. Emergency contact information and escalation procedures are maintained in the incident response toolkit.', false, 'No exceptions permitted for incident response requirements due to safety and regulatory obligations.', '{b45bb933-8abd-4978-9a04-695664db5a0f,485368a5-8626-44de-85a2-762de93c2825}', '{1a8ee9bc-8687-493a-8d3a-55aed64e26a6}', '{"NERC CIP-008-6","NIST CSF RS.RP-1","NIST CSF RS.CO-1"}', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2023-08-30 16:00:00+00', '2023-09-05 10:00:00+00', 'Policy approved with enhanced coordination procedures between IT and OT teams', 'Emergency Response Manager', 'Emergency Response Manager', '{"Incident Response Team","Operations Control Center","Cybersecurity Team","Engineering Team"}', 'https://policies.dewa.gov.ae/transmission/incident-response-v3.0.pdf', '3.0', '{"Cyber Incident Response Plan","Emergency Contact Directory","Regulatory Reporting Guide"}', true, '{"Incident Response Training","Tabletop Exercise Materials","Crisis Communication Guide"}', true, true, '2026-02-13 09:06:05.51224+00', 100.00, '{incident-response,emergency,coordination,critical}', 'Major revision to align with updated NERC CIP requirements and enhance OT/IT coordination', '2026-02-13 09:06:05.51224+00', '2026-02-13 09:06:05.51224+00'),
	('59dbe216-5904-43a5-a5ae-9be4ddf01972', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-CRY-001', 'Encryption and Key Management Policy', 'Controls for protecting cryptographic keys and defining encryption standards.', 'Data Protection', '1.0', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2024-01-01 00:00:00+00', '2025-01-01 00:00:00+00', NULL, 12, 'enterprise', 'mandatory', NULL, NULL, NULL, NULL, 'All cryptographic keys must be stored in hardware security modules and rotated every 6 months.', 'To ensure the confidentiality and integrity of sensitive enterprise and operational data.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Chief Information Security Officer', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 98.50, '{encryption,key-management,pki}', 'New policy for 2024', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('730b28b1-a2cc-42ed-ad5d-8743cb05f34b', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-REM-001', 'Secure Remote Access Policy', 'Governs all remote connections to the SCADA and control networks.', 'Access Control', '2.3', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2023-08-15 00:00:00+00', '2024-08-15 00:00:00+00', NULL, 12, 'transmission', 'mandatory', NULL, NULL, NULL, NULL, 'Remote access is only permitted via MFA-enabled VPN and must be tunnelled through a jump host.', 'To prevent unauthorized remote entry into critical grid control systems.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'OT Security Manager', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 92.00, '{remote-access,vpn,scada}', 'Updated after last audit findings', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('91991456-28e5-4126-bbf4-132bd218ef99', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-SUP-001', 'Supply Chain Cybersecurity Policy', 'Cybersecurity requirements for all vendors and equipment suppliers.', 'Vendor Management', '1.1', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2023-11-01 00:00:00+00', '2024-11-01 00:00:00+00', NULL, 12, 'enterprise', 'mandatory', NULL, NULL, NULL, NULL, 'Vendors must provide a Software Bill of Materials (SBOM) for all delivered software and firmware.', 'To mitigate risks introduced through third-party hardware and software.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Procurement Director', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 85.00, '{supply-chain,vendor,sbom}', 'Crucial for NERC CIP-013 compliance', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('1d230b80-eecc-4570-830e-0fa847b886fe', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-VUL-001', 'Vulnerability Management Policy', 'Standards for identifying, assessing, and remediating security vulnerabilities.', 'System Integrity', '3.0', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2023-06-01 00:00:00+00', '2024-06-01 00:00:00+00', NULL, 12, 'enterprise', 'mandatory', NULL, NULL, NULL, NULL, 'Critical vulnerabilities must be remediated within 7 days; high within 30 days.', 'To maintain a secure and resilient operational environment.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'IT Security Manager', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 78.40, '{vulnerability,patching,remediation}', 'Higher frequency scans required for HMI nodes', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('0a74624a-7940-47bb-9834-50d76f8c729b', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-TRA-001', 'Personnel Security and Awareness Policy', 'Expectations for staff training and behavioral security controls.', 'Personnel Security', '1.0', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2024-01-10 00:00:00+00', '2025-01-10 00:00:00+00', NULL, 12, 'enterprise', 'mandatory', NULL, NULL, NULL, NULL, 'All employees must complete annual security awareness training and a role-specific OT security module.', 'To minimize risk of human error and social engineering attacks.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Human Resources Director', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 100.00, '{training,awareness,personnel}', 'New mandatory training for 2024', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('51e5911e-2d1e-4b04-aecd-97b89be969ca', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-INC-002', 'Cyber-Forensics and Evidence Policy', 'Standards for handling evidence after a cybersecurity incident.', 'Incident Response', '1.0', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'draft', '2024-03-01 00:00:00+00', '2025-03-01 00:00:00+00', NULL, 12, 'enterprise', 'recommended', NULL, NULL, NULL, NULL, 'Evidence must be captured using write-blocked devices and maintained in a chain of custody.', 'To ensure legal and regulatory validity of forensic findings.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Legal Counsel', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 0.00, '{forensics,evidence,legal}', 'Awaiting legal review', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('0bc05239-6aa4-48df-ae25-f238aed9cd5c', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-PHY-001', 'Substation Physical Security Policy', 'Standard for physical access controls at transmission substations.', 'Physical Security', '2.0', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2023-05-15 00:00:00+00', '2024-05-15 00:00:00+00', NULL, 24, 'site-specific', 'mandatory', NULL, NULL, NULL, NULL, 'Substation gates must be alarmed and monitored by CCTV with 90-day retention.', 'To prevent physical tampering with critical grid infrastructure.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Facilities Manager', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 96.00, '{physical,cctv,alarms}', 'Retention increased from 30 to 90 days', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('39e669e5-338e-485d-8179-27d52233eb37', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-CHG-001', 'Operational Change Management Policy', 'Controls for modifying configurations of operational systems.', 'Change Management', '1.5', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2023-09-01 00:00:00+00', '2024-09-01 00:00:00+00', NULL, 12, 'transmission', 'mandatory', NULL, NULL, NULL, NULL, 'All changes to protection relay settings must be reviewed by two engineers and tested in a simulator.', 'To prevent accidental misconfiguration leading to grid instability.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Operations Manager', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 100.00, '{change-management,engineering,safety}', 'Zero-tolerance for unauthorized changes', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('b7c94f95-25dd-4c92-8839-4d1546a9f2c7', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-LOG-001', 'Security Logging and Auditing Policy', 'Requirements for event generation and log retention across all systems.', 'Monitoring', '2.1', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2023-10-15 00:00:00+00', '2024-10-15 00:00:00+00', NULL, 12, 'enterprise', 'mandatory', NULL, NULL, NULL, NULL, 'Security event logs must be offloaded to SIEM in real-time and retained for 3 years for CIP assets.', 'To enable detection of breaches and support post-incident investigations.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SOC Manager', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 89.20, '{logging,audit,siem}', 'Retention updated for regulatory alignment', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('d3e2ab79-2b95-4f17-b67f-cab427aa320c', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-PAS-001', 'Password and Secret Complexity Policy', 'Standards for password length, history, and secret management.', 'Access Control', '4.0', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2024-01-01 00:00:00+00', '2025-01-01 00:00:00+00', NULL, 12, 'enterprise', 'mandatory', NULL, NULL, NULL, NULL, 'Passwords for local accounts must be 14 characters minimum with no reuse for last 10 versions.', 'To protect against credential-based attacks.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Identity Manager', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 94.00, '{passwords,secrets,complexity}', 'Applied to all non-integrated local accounts', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('7b86faaf-b727-4b0c-a559-8407cb1574b3', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-DIS-001', 'Disaster Recovery and Business Continuity Policy', 'Framework for restoring critical services after massive failures.', 'Continuity', '2.2', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2023-07-20 00:00:00+00', '2024-07-20 00:00:00+00', NULL, 12, 'enterprise', 'mandatory', NULL, NULL, NULL, NULL, 'Recovery time objective (RTO) for SCADA is 4 hours; recovery point objective (RPO) is 15 minutes.', 'To ensure grid resilience during major physical or cyber events.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Business Continuity Manager', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 84.50, '{disaster-recovery,continuity,resilience}', 'Tabletop exercise conducted in Nov 2023', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00'),
	('c070168d-9ad3-46e1-8a0b-ec9cfb883073', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'POL-EXT-001', 'Exceptions and Waivers Policy', 'Procedure for requesting temporary deviation from security standards.', 'Governance', '1.0', '2026-02-13 09:06:06.425609+00', NULL, NULL, 'active', '2023-12-01 00:00:00+00', '2024-12-01 00:00:00+00', NULL, 12, 'enterprise', 'mandatory', NULL, NULL, NULL, NULL, 'All security policy exceptions must have a defined expiration and an approved compensating control.', 'To manage risk when technical or operational constraints prevent policy adherence.', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Risk Manager', NULL, NULL, NULL, NULL, NULL, false, NULL, true, true, NULL, 100.00, '{exceptions,governance,risk}', 'Ensures tracking of all non-compliant states', '2026-02-13 09:06:06.425609+00', '2026-02-13 09:06:06.425609+00');
INSERT INTO "public"."security_exceptions" ("id", "tenant_id", "exception_id", "exception_name", "exception_type", "policy_id", "control_id", "requirement_id", "standard_id", "scope", "applies_to_sites", "applies_to_zones", "applies_to_assets", "applies_to_users", "requested_by", "request_date", "business_justification", "technical_justification", "alternative_controls", "risk_level", "risk_description", "risk_mitigation_measures", "residual_risk_level", "residual_risk_description", "status", "reviewed_by", "review_date", "review_comments", "approved_by", "approval_date", "approval_conditions", "denial_reason", "effective_date", "expiration_date", "auto_expire", "extension_allowed", "max_extensions", "extensions_used", "requires_monitoring", "monitoring_frequency_days", "last_monitored", "next_monitoring_date", "compliance_status", "compensating_controls_required", "compensating_controls", "compensating_controls_implemented", "compensating_controls_verified", "revoked", "revoked_by", "revocation_date", "revocation_reason", "audit_log", "tags", "notes", "created_at", "updated_at") VALUES
	('6fcc1581-0f46-4add-88b4-025abf89a03a', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'EXC-TRANS-001', 'Legacy Protection Relay IEC 62351 Exception', 'control-exception', NULL, '541c6477-296e-4135-8c13-b4ab3badc800', NULL, NULL, 'asset', '{NULL}', '{protection-systems}', NULL, NULL, '2b95d280-9ec0-4aa1-b1d3-6bb4b13f82de', '2024-01-10 10:00:00+00', 'Legacy protection relays at Al Aweer Substation do not support IEC 62351 security extensions. Replacement scheduled for Q3 2024 but current relays are critical for system protection.', 'Existing Schneider P543 relays manufactured in 2015 do not have firmware capability for IEC 62351. Hardware replacement required but cannot be performed until planned outage window.', 'Enhanced network monitoring, dedicated VLAN isolation, and additional physical security controls implemented', 'medium', 'Legacy relays communicate using unencrypted IEC 61850 GOOSE messages, potentially vulnerable to man-in-the-middle attacks', '{"Isolated VLAN with strict firewall rules","Enhanced physical security at relay panels","Continuous network monitoring with anomaly detection","Regular security assessments and penetration testing"}', 'low', 'With compensating controls, residual risk reduced to acceptable level until hardware replacement', 'approved', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2024-01-15 14:00:00+00', 'Exception approved based on strong compensating controls and definitive replacement timeline', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2024-01-18 16:00:00+00', '{"Hardware replacement must be completed by September 30, 2024","Monthly security monitoring reports required","Any security incidents must trigger immediate review"}', NULL, '2024-01-20 00:00:00+00', '2024-09-30 23:59:59+00', true, true, 1, 0, true, 30, '2024-01-20 09:00:00+00', '2024-02-20 09:00:00+00', 'compliant', true, '{"Dedicated VLAN with firewall protection","Enhanced physical access controls","Continuous network monitoring","Monthly security assessments"}', true, true, false, NULL, NULL, NULL, '[]', '{legacy-equipment,protection-relays,iec-62351,temporary}', 'Exception granted for legacy equipment with strong compensating controls', '2026-02-13 09:06:05.61712+00', '2026-02-13 09:06:05.61712+00'),
	('2fccb0c1-4756-4ce6-900c-ce3cacbe11b3', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'EXC-TRANS-002', 'Emergency SCADA Access Without MFA', 'policy-exception', '876e949a-3646-4d16-8cdc-d6a72db17cc7', NULL, NULL, NULL, 'system', NULL, '{scada-network}', NULL, NULL, '2e4ba450-22f8-42d5-b89c-3e497829289b', '2024-01-05 08:00:00+00', 'During major grid emergencies, operators may need immediate SCADA access when MFA tokens are unavailable or malfunctioning. Grid stability takes precedence over security controls.', 'Emergency situations may occur outside normal hours when MFA token support is limited. Backup authentication methods needed for critical system restoration.', 'Emergency access accounts with strong passwords, immediate logging, and mandatory post-incident review', 'high', 'Emergency access without MFA increases risk of unauthorized access during critical periods', '{"Emergency access limited to designated senior operators","All emergency access logged and monitored in real-time","Mandatory security review within 4 hours","Emergency access automatically expires after 24 hours"}', 'medium', 'With strict controls and immediate review, risk is manageable for emergency situations', 'approved', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2024-01-08 11:00:00+00', 'Exception approved for genuine emergencies with strict monitoring and review requirements', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2024-01-10 09:00:00+00', '{"Emergency access only for declared grid emergencies","Maximum 3 designated emergency accounts","All usage must be reviewed within 4 hours","Annual review of emergency access procedures"}', NULL, '2024-01-15 00:00:00+00', '2025-01-15 00:00:00+00', true, true, 2, 0, true, 7, '2024-01-15 10:00:00+00', '2024-01-22 10:00:00+00', 'compliant', true, '{"Real-time access monitoring and alerting","Mandatory post-incident security review","Emergency access session recording","Immediate notification to security team"}', true, true, false, NULL, NULL, NULL, '[]', '{emergency-access,grid-emergency,mfa-exception,high-risk}', 'Critical exception for grid emergency situations with comprehensive monitoring', '2026-02-13 09:06:05.61712+00', '2026-02-13 09:06:05.61712+00'),
	('e7acbb6b-4e89-490f-91ba-eba00805689c', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'WAIV-TRANS-001', 'Vendor Remote Access Compliance Waiver', 'compliance-waiver', NULL, NULL, '6fe473d0-3ab2-460f-93eb-e587a8fcf5c1', NULL, 'system', NULL, '{maintenance-network}', NULL, NULL, 'fd159233-57ce-4300-99b5-22a04155a53b', '2023-12-20 14:00:00+00', 'Critical protection relay firmware updates require vendor remote access using proprietary tools that do not integrate with our RBAC system. Vendor access is essential for system reliability.', 'Vendor proprietary maintenance tools cannot authenticate through our Active Directory system. Direct relay access required for firmware updates and diagnostics.', 'Dedicated vendor access network segment with enhanced monitoring and session recording', 'medium', 'Vendor access bypasses standard role-based access controls, creating potential for unauthorized actions', '{"Vendor access limited to dedicated network segment","All vendor sessions recorded and monitored","Vendor personnel must be escorted by DEWA staff","Access limited to specific maintenance windows"}', 'low', 'Compensating controls and supervision reduce risk to acceptable levels', 'approved', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2023-12-28 10:00:00+00', 'Waiver approved based on operational necessity and strong compensating controls', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2024-01-02 13:00:00+00', '{"Vendor access only during approved maintenance windows","DEWA staff must supervise all vendor activities","Session recordings must be reviewed within 24 hours","Quarterly review of vendor access procedures"}', NULL, '2024-01-05 00:00:00+00', '2024-07-05 00:00:00+00', true, true, 1, 0, true, 14, '2024-01-05 12:00:00+00', '2024-01-19 12:00:00+00', 'compliant', true, '{"Dedicated vendor network segment","Session recording and monitoring","Mandatory staff supervision","Access time restrictions"}', true, true, false, NULL, NULL, NULL, '[]', '{vendor-access,maintenance,rbac-waiver,supervised}', 'Operational necessity waiver with comprehensive oversight controls', '2026-02-13 09:06:05.61712+00', '2026-02-13 09:06:05.61712+00'),
	('25fbd41a-0266-4fb4-8df5-728e16d58a16', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'DEV-TRANS-001', 'SCADA System Upgrade Security Deviation', 'temporary-deviation', '83519ac0-41d0-4cea-924a-470e09aab586', NULL, NULL, NULL, 'system', '{ea3fb3ce-4437-4983-8c2b-fec72a1775d6}', '{scada-network}', NULL, NULL, '4ba4b9a3-1ea1-413f-86bf-13565f150d35', '2024-01-12 16:00:00+00', 'SCADA system upgrade requires temporary relaxation of network segmentation rules to allow data migration between old and new systems.', 'System upgrade process requires direct network connectivity between legacy and new SCADA systems for data migration. Standard network segmentation must be temporarily modified.', 'Enhanced monitoring during migration period with dedicated security personnel oversight', 'medium', 'Temporary network configuration changes may create additional attack vectors during migration', '{"Migration limited to scheduled maintenance window","Dedicated security monitoring during entire process","Network changes documented and approved","Immediate restoration of segmentation post-migration"}', 'low', 'Short duration and enhanced monitoring minimize residual risk', 'approved', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2024-01-15 09:00:00+00', 'Deviation approved for critical system upgrade with enhanced monitoring', 'fd159233-57ce-4300-99b5-22a04155a53b', '2024-01-16 11:00:00+00', '{"Migration must be completed within 48-hour window","Security team must monitor entire process","Network segmentation must be restored immediately","Post-migration security validation required"}', NULL, '2024-01-20 00:00:00+00', '2024-01-22 23:59:59+00', true, false, 0, 0, true, 1, '2024-01-20 08:00:00+00', '2024-01-21 08:00:00+00', 'compliant', true, '{"Continuous security monitoring","Dedicated security personnel oversight","Real-time network traffic analysis","Immediate incident response capability"}', true, true, false, NULL, NULL, NULL, '[]', '{system-upgrade,temporary,network-segmentation,migration}', 'Short-term deviation for critical system upgrade with intensive monitoring', '2026-02-13 09:06:05.61712+00', '2026-02-13 09:06:05.61712+00');
