	('893b41a0-f085-412e-8f4a-0669130ce642', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '6fcc1581-0f46-4add-88b4-025abf89a03a', '2b95d280-9ec0-4aa1-b1d3-6bb4b13f82de', '2024-08-15 14:00:00+00', 'Hardware delivery delayed by 6 weeks due to supply chain issues. Vendor confirms new delivery date of November 15, 2024.', '2024-11-30 23:59:59+00', 'approved', '2e4ba450-22f8-42d5-b89c-3e497829289b', '2024-08-20 11:00:00+00', '2024-11-30 23:59:59+00', '{"Enhanced monitoring during extension period","Weekly status reports on hardware delivery","No further extensions permitted"}', NULL, 'Extension approved due to supply chain delays beyond DEWA control. This is the final extension.', '2026-02-13 09:06:05.61712+00', '2026-02-13 09:06:05.61712+00');
