	('255f642d-dd31-44a7-9cda-96422c472b78', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '2fccb0c1-4756-4ce6-900c-ce3cacbe11b3', '2024-01-18 02:30:00+00', 'security-event', 'Emergency SCADA access used during grid disturbance event. Access properly authorized and documented.', 'low', 'No security impact. Emergency access used appropriately during legitimate grid emergency.', '{"SCADA system","Emergency access account"}', NULL, '{"Emergency access logged and monitored","Security team notified immediately","Post-incident review completed within 4 hours","Access session recorded and reviewed"}', false, NULL, 'completed', true, false, NULL, NULL, 'Proper use of emergency access exception during legitimate grid emergency. All procedures followed correctly.', '2026-02-13 09:06:05.61712+00', '2026-02-13 09:06:05.61712+00');
