	('94d7a9d5-ad0e-4453-a6ff-3c10ae5dc6f5', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '6fcc1581-0f46-4add-88b4-025abf89a03a', '2024-01-20 09:00:00+00', 'initial', 'ffb10062-9448-4e54-b354-f0f3e16e33bf', 'Security Analyst', 'Compensating controls are functioning effectively. Network monitoring shows no anomalous activity. Physical security enhancements verified.', true, true, true, 'continue', 'Exception controls are working well. Recommend continuing with current monitoring approach.', '{"Verify hardware replacement timeline","Review monthly monitoring reports"}', true, '2024-02-20 09:00:00+00', false, 'Initial review shows strong control implementation. Hardware replacement on track.', '2026-02-13 09:06:05.61712+00', '2026-02-13 09:06:05.61712+00'),
	('a7c3ab08-9655-441e-b31a-771b3ce39967', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '2fccb0c1-4756-4ce6-900c-ce3cacbe11b3', '2024-01-15 10:00:00+00', 'initial', '2e4ba450-22f8-42d5-b89c-3e497829289b', 'Security Manager', 'Emergency access procedures documented and tested. No unauthorized usage detected. Monitoring systems functioning correctly.', true, true, true, 'continue', 'Exception is well-controlled with appropriate monitoring. Continue current approach.', '{"Test emergency access procedures quarterly","Review access logs weekly"}', true, '2024-01-22 10:00:00+00', false, 'Emergency access controls properly implemented. Regular testing recommended.', '2026-02-13 09:06:05.61712+00', '2026-02-13 09:06:05.61712+00');
