INSERT INTO "public"."network_exposure_assessments" ("id", "tenant_id", "site_id", "asset_id", "zone_id", "assessment_type", "exposure_level", "risk_score", "findings_count", "critical_findings", "high_findings", "medium_findings", "low_findings", "exposed_services", "exposed_ports", "vulnerable_protocols", "mitigation_status", "mitigation_recommendations", "assessment_date", "next_assessment_date", "assessor", "automated", "findings_summary", "detailed_findings", "metadata", "created_at", "updated_at") VALUES
	('f3545bd6-40ec-44c4-ba04-30299f166ef4', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'ea3fb3ce-4437-4983-8c2b-fec72a1775d6', NULL, '17ecc9a6-ff7e-46a9-b3cb-6f5b3ff66fd3', 'vulnerability-scan', 'medium', 55, 12, 0, 3, 7, 2, '[{"port": 20000, "service": "DNP3", "version": "IEEE 1815-2012"}, {"port": 102, "service": "IEC 61850 MMS", "version": "Edition 2"}, {"port": 443, "service": "HTTPS", "version": "TLS 1.2"}]', '[20000, 102, 443, 502, 8080]', '[{"protocol": "MODBUS", "severity": "high", "vulnerability": "No authentication"}, {"protocol": "SNMP", "severity": "medium", "vulnerability": "SNMPv2c in use"}]', 'in-progress', '[{"priority": "high", "recommendation": "Upgrade MODBUS to MODBUS/TCP with authentication"}, {"priority": "medium", "recommendation": "Migrate from SNMPv2c to SNMPv3"}, {"priority": "medium", "recommendation": "Update TLS to version 1.3"}]', '2026-01-29 09:06:05.038343+00', '2026-04-29 09:06:05.038343+00', 'Sarah Al Nuaimi', true, 'Automated vulnerability scan identified 12 findings across SCADA network. No critical vulnerabilities found. Three high-priority findings related to legacy protocol security.', '{"scan_tool": "Nessus Professional", "scan_policy": "ICS/SCADA Security Audit", "assets_scanned": 28, "scan_duration_minutes": 45}', '{"scan_id": "SCAN-2024-0156", "compliance_frameworks": ["IEC 62443", "NERC CIP"]}', '2026-01-29 09:06:05.038343+00', '2026-02-03 09:06:05.038343+00'),
	('5ba57688-3fec-43dd-8135-3eff21a557a8', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '6f415f6b-cb50-4da2-85d8-1025d6f9c119', NULL, '64d1b2e3-7467-4bad-a470-ac4daec3a64b', 'penetration-test', 'low', 25, 5, 0, 0, 3, 2, '[{"port": 102, "service": "IEC 61850 MMS", "version": "Edition 2.1", "authentication": "certificate-based"}]', '[102]', '[]', 'completed', '[{"priority": "medium", "recommendation": "Implement network segmentation for individual relay groups"}, {"priority": "low", "recommendation": "Enable additional logging for MMS operations"}]', '2025-12-30 09:06:05.038343+00', '2026-12-30 09:06:05.038343+00', 'External Security Firm - CyberOT Solutions', false, 'Comprehensive penetration test of protection systems zone. Strong security posture confirmed. No critical or high-risk findings. Zone demonstrates IEC 62443 SL4 compliance.', '{"test_methodology": "PTES", "test_duration_days": 3, "successful_exploits": 0, "attack_vectors_tested": ["network", "physical", "social_engineering"]}', '{"report_id": "PENTEST-2024-JA-001", "certification": "IEC 62443 SL4"}', '2025-12-30 09:06:05.038343+00', '2026-01-04 09:06:05.038343+00'),
	('a7138eeb-874e-4d8c-b92c-9e2db31acf21', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '6f415f6b-cb50-4da2-85d8-1025d6f9c119', 'fd13d1b9-def3-4b8a-aa21-6d96f015c4aa', '64d1b2e3-7467-4bad-a470-ac4daec3a64b', 'configuration-audit', 'high', 72, 8, 1, 2, 4, 1, '[{"port": 23, "status": "enabled", "service": "Telnet"}, {"port": 80, "status": "enabled", "service": "HTTP"}, {"port": 22, "status": "enabled", "service": "SSH"}]', '[23, 80, 22, 102]', '[{"protocol": "Telnet", "severity": "critical", "vulnerability": "Unencrypted management protocol"}, {"protocol": "HTTP", "severity": "high", "vulnerability": "Unencrypted web interface"}]', 'pending', '[{"priority": "critical", "recommendation": "Disable Telnet immediately, use SSH only"}, {"priority": "high", "recommendation": "Disable HTTP, enable HTTPS with strong cipher suites"}, {"priority": "medium", "recommendation": "Implement certificate-based SSH authentication"}, {"priority": "medium", "recommendation": "Enable SNMP v3 for monitoring"}]', '2026-02-06 09:06:05.038343+00', '2026-05-07 09:06:05.038343+00', 'Mohammed bin Rashid', false, 'Configuration audit revealed critical security gaps in legacy protection relay. Telnet and HTTP services enabled, creating significant security exposure. Immediate remediation required.', '{"device_model": "SEL-351", "firmware_version": "R114-V0-Z001-D20110209", "compliance_status": "non-compliant", "last_config_change": "2023-08-15"}', '{"audit_id": "CFG-AUDIT-2024-0089", "remediation_deadline": "2024-02-01"}', '2026-02-06 09:06:05.038343+00', '2026-02-08 09:06:05.038343+00'),
	('90bdf546-f18e-485d-b3cd-aab06bbb523d', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '87a51493-079a-4d9a-a3f9-fb06b16ba596', NULL, '0d99b1f6-2664-41bd-849b-93289d31226a', 'network-scan', 'medium', 48, 15, 0, 2, 9, 4, '[{"port": 502, "devices": 12, "service": "MODBUS/TCP"}, {"port": 20000, "devices": 8, "service": "DNP3"}, {"port": 80, "devices": 5, "service": "HTTP"}]', '[502, 20000, 80, 161, 8080]', '[{"protocol": "MODBUS", "severity": "high", "vulnerability": "No encryption"}, {"protocol": "SNMP", "severity": "medium", "vulnerability": "Community strings in use"}]', 'in-progress', '[{"priority": "high", "recommendation": "Implement VPN for MODBUS communications"}, {"priority": "medium", "recommendation": "Upgrade to DNP3 Secure Authentication"}, {"priority": "medium", "recommendation": "Disable HTTP on field devices, use HTTPS"}]', '2026-01-24 09:06:05.038343+00', '2026-04-24 09:06:05.038343+00', 'Automated Scanner', true, 'Network scan of field devices zone identified 15 findings. Two high-priority issues related to unencrypted industrial protocols. Mitigation plan in progress.', '{"scan_tool": "Nmap + NSE Scripts", "network_range": "10.20.25.0/24", "devices_discovered": 25, "scan_duration_minutes": 30}', '{"scan_id": "NETSCAN-2024-0234", "zone_type": "field-devices"}', '2026-01-24 09:06:05.038343+00', '2026-01-29 09:06:05.038343+00'),
	('41a77165-1732-4948-8c1d-a6674504711d', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '6f415f6b-cb50-4da2-85d8-1025d6f9c119', NULL, '64d1b2e3-7467-4bad-a470-ac4daec3a64b', 'protocol-analysis', 'low', 18, 3, 0, 0, 2, 1, '[{"port": 102, "service": "IEC 61850 MMS", "encryption": "TLS 1.2"}, {"service": "IEC 61850 GOOSE", "multicast": "01-0C-CD-01-00-00"}]', '[102]', '[]', 'completed', '[{"priority": "medium", "recommendation": "Implement GOOSE message authentication per IEC 62351"}, {"priority": "low", "recommendation": "Enable MMS operation logging for forensics"}]', '2026-01-14 09:06:05.038343+00', '2026-07-13 09:06:05.038343+00', 'Omar Al Falasi', false, 'Deep packet inspection of IEC 61850 traffic shows proper implementation of security features. MMS communications properly encrypted. GOOSE messages lack authentication (common for legacy deployments).', '{"analysis_tool": "Wireshark + IEC 61850 Dissector", "packets_analyzed": 1250000, "protocols_detected": ["MMS", "GOOSE", "SV"], "capture_duration_hours": 24}', '{"analysis_id": "PROTO-2024-IEC61850-001", "standard_compliance": "IEC 61850-8-1"}', '2026-01-14 09:06:05.038343+00', '2026-01-19 09:06:05.038343+00'),
