	('bd036548-fb4c-4a4c-b6c3-b86b87acd111', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'RISK-TX-001', 'IEC 61850 GOOSE Message Manipulation', 'Unauthorized manipulation of IEC 61850 GOOSE messages could cause protection relay misoperation, leading to cascading grid failures and equipment damage.', 'cyber-attack', 'protocol-manipulation', 'Attacker intercepts and modifies GOOSE messages to cause protection relay misoperation', 'nation-state', '{network-interception,protocol-manipulation,man-in-the-middle}', '{protection-relays,substation-automation,transmission-lines}', '{IEC-61850,GOOSE}', NULL, NULL, NULL, 'medium', 'catastrophic', 60.00, 'high', 'medium', 'major', 48.00, 'medium', false, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, 'partially-effective', NULL, 'mitigate', NULL, 'Cybersecurity Team Lead', NULL, NULL, NULL, 'mitigating', '2026-02-13 09:06:05.330949+00', 'Security Analyst', NULL, '2024-03-15 10:00:00+00', 6, false, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, true, 30, NULL, '2024-02-15 10:00:00+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Requires immediate implementation of IEC 62351 security extensions for encrypted GOOSE communications', '2026-02-13 09:06:05.330949+00', '2026-02-13 09:06:05.330949+00'),
	('ca018430-aa0e-4310-9b41-84f197a8d4f8', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'RISK-TX-002', 'SCADA System Compromise', 'Compromise of SCADA systems could allow attackers to manipulate grid operations, causing load shedding, equipment damage, or blackouts.', 'cyber-attack', 'system-compromise', 'Advanced persistent threat gains access to SCADA systems through spear-phishing or supply chain attack', 'nation-state', '{spear-phishing,supply-chain-attack,lateral-movement}', '{scada-systems,control-centers,transmission-substations}', '{DNP3,IEC-60870-5-104}', NULL, NULL, NULL, 'medium', 'major', 48.00, 'medium', 'medium', 'major', 48.00, 'medium', false, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, 'partially-effective', NULL, 'mitigate', NULL, 'Operations Manager', NULL, NULL, NULL, 'assessed', '2026-02-13 09:06:05.330949+00', 'Security Analyst', NULL, '2024-04-01 14:00:00+00', 6, false, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, true, 30, NULL, '2024-02-01 14:00:00+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Multi-factor authentication and network micro-segmentation implementation in progress', '2026-02-13 09:06:05.330949+00', '2026-02-13 09:06:05.330949+00'),
	('c51d4437-aeca-495c-8bbb-47b9091d5599', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'RISK-TX-003', 'Privileged User Account Misuse', 'Misuse of privileged accounts by insiders could result in unauthorized configuration changes, data theft, or system sabotage.', 'insider-threat', 'privilege-abuse', 'Malicious insider uses privileged access to modify protection settings or steal sensitive operational data', 'insider', '{privilege-escalation,data-exfiltration,system-sabotage}', '{control-systems,protection-settings,operational-data}', '{IEC-61850,DNP3}', NULL, NULL, NULL, 'low', 'major', 32.00, 'low', 'low', 'moderate', 24.00, 'low', false, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, 'effective', NULL, 'mitigate', NULL, 'Security Manager', NULL, NULL, NULL, 'monitoring', '2026-02-13 09:06:05.330949+00', 'Security Analyst', NULL, '2024-05-01 09:00:00+00', 6, false, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, true, 30, NULL, '2024-02-20 09:00:00+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Privileged access management system deployment scheduled for Q2 2024', '2026-02-13 09:06:05.330949+00', '2026-02-13 09:06:05.330949+00'),
	('9656a876-618e-4ba5-a3fa-c78b25abc86b', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'RISK-TX-004', 'Protection Relay Firmware Vulnerabilities', 'Unpatched firmware vulnerabilities in protection relays could be exploited to cause relay malfunction or unauthorized access to protection settings.', 'system-vulnerability', 'firmware-vulnerability', 'Attacker exploits known firmware vulnerability to gain control of protection relay', 'criminal', '{remote-exploitation,firmware-manipulation,configuration-change}', '{protection-relays,differential-protection,distance-protection}', '{IEC-61850,DNP3}', NULL, NULL, NULL, 'medium', 'major', 48.00, 'medium', 'low', 'moderate', 24.00, 'low', false, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, 'partially-effective', NULL, 'mitigate', NULL, 'Engineering Manager', NULL, NULL, NULL, 'identified', '2026-02-13 09:06:05.330949+00', 'Security Analyst', NULL, '2024-03-30 16:00:00+00', 6, false, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, true, 30, NULL, '2024-02-28 16:00:00+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Firmware vulnerability assessment and patching program under development', '2026-02-13 09:06:05.330949+00', '2026-02-13 09:06:05.330949+00'),
