	('f6395fdb-aa45-4f5b-b5b3-8b04cf8d83e2', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'Fortinet', 'FORTI-001', 'equipment-manufacturer', 'David Chen', 'david.chen@fortinet.com', '+1-555-0321', 'FortiGate 3000D Firewall', '7.2.3', 'gateway', 'production-critical', '2026-01-24 09:06:05.182626+00', 'periodic', 'Mohammed bin Rashid', 'combined', 90.00, 20.00, 'trusted', 95.00, 92.00, 90.00, 95.00, 88.00, 90.00, '{"Common Criteria EAL4+","FIPS 140-2","ICSA Labs Certified"}', '{"NERC CIP","NIST CSF","PCI DSS"}', false, 0, 2, 0, 0, 1, 1, 0, 0, 1, 1, 'Fortinet FortiGate demonstrates excellent security with Common Criteria EAL4+ certification. Strong threat protection and VPN capabilities. Minor finding related to firmware update scheduling.', '{"Implement automated firmware update testing in lab environment","Enable advanced threat protection features","Configure geo-blocking for non-essential countries","Enhance logging integration with SIEM"}', '{"Schedule firmware updates during maintenance windows","Enable ATP features on all security policies","Configure enhanced logging"}', 'Firmware update process being automated. ATP features deployment in progress. SIEM integration enhancement scheduled for Q1 2024.', '2026-03-30 09:06:05.182626+00', '2021-09-01 00:00:00+00', '2026-08-31 00:00:00+00', '99.99% availability, 1-hour response for critical issues, monthly firmware updates, 24/7 support', 'Common Criteria EAL4+, FIPS 140-2, encrypted management, role-based administration, comprehensive logging', 'completed', 'approved', 'Mohammed bin Rashid', '2026-02-03 09:06:05.182626+00', '2026-08-12 09:06:05.182626+00', 'semi-annual', 'Comprehensive assessment including penetration testing. Fortinet security practices exemplary.', NULL, '2026-01-24 09:06:05.182626+00', '2026-02-03 09:06:05.182626+00'),
