INSERT INTO "public"."vendor_contact_history" ("id", "assessment_id", "tenant_id", "contact_date", "contact_type", "contact_subject", "contact_summary", "internal_participants", "vendor_participants", "action_items", "follow_up_required", "follow_up_date", "attachments", "created_at") VALUES
	('87218a22-12db-490b-b1a7-d203c4e97177', '7c4f4360-7207-49c0-b837-fead1e280ca2', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '2025-12-20 09:06:05.182626+00', 'meeting', 'Security Assessment Kickoff Meeting', 'Initial meeting to discuss security assessment scope, methodology, and timeline. GE provided overview of Mark VIe security features and certifications. Agreed on assessment schedule and access requirements.', '{"Fatima Al Zahra","Ahmed Al Mansouri","Sarah Al Nuaimi"}', '{"John Anderson","Michael Roberts (GE Security)"}', '{"GE to provide security documentation and certifications","DEWA to schedule on-site audit for week of Jan 15","GE to arrange access to engineering workstations"}', true, '2025-12-25 09:06:05.182626+00', NULL, '2025-12-20 09:06:05.182626+00'),
	('96fc5900-1d56-4f2a-ae08-1072544394ad', '7c4f4360-7207-49c0-b837-fead1e280ca2', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '2026-02-03 09:06:05.182626+00', 'email', 'Remediation Plan Discussion', 'Email exchange regarding remediation timeline for identified findings. GE committed to credential changes within 30 days and firmware upgrade during Q2 maintenance window. Discussed lab testing requirements.', '{"Fatima Al Zahra"}', '{"John Anderson"}', '{"GE to provide firmware upgrade procedure by Feb 15","DEWA to set up lab environment for testing","Schedule follow-up call for March 1"}', true, '2026-03-05 09:06:05.182626+00', NULL, '2026-02-03 09:06:05.182626+00'),
	('9fa31ab9-3294-41c6-8bda-ee74f79a000c', 'e972c223-922a-4ef2-b4f4-eca241a6eb3b', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '2026-01-19 09:06:05.182626+00', 'meeting', 'On-Site Security Audit', 'Comprehensive on-site audit of ClearSCADA installation. Reviewed system architecture, security configuration, access controls, and logging. Identified database encryption gap. Schneider provided immediate recommendations.', '{"Mohammed bin Rashid","Ahmed Al Mansouri"}', '{"Marie Dubois","Thomas Mueller (Schneider Security)"}', '{"Schneider to provide TDE implementation guide","DEWA to assess HSM requirements for key management","Schedule database encryption implementation for Q1 2024"}', true, '2026-02-08 09:06:05.182626+00', NULL, '2026-01-19 09:06:05.182626+00'),
	('36d19a4a-40db-4d3e-b744-59e5bcb0e295', '6cd1c754-c488-4b4d-baec-612a8833392a', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '2026-02-03 09:06:06.454999+00', 'email', 'Telnet Vulnerability Patch Request', 'Requested patch for Telnet vulnerability. No response yet.', '{"Security Team"}', '{"Ibrahim Khan"}', NULL, false, NULL, NULL, '2026-02-13 09:06:06.454999+00'),
	('09e6e214-3901-4594-9202-190daad2c53d', '6cd1c754-c488-4b4d-baec-612a8833392a', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', '2026-02-11 09:06:06.454999+00', 'phone', 'Patch Follow-up', 'Followed up on patch. Vendor claims system is end-of-life.', '{"Security Team"}', '{"Ibrahim Khan"}', NULL, false, NULL, NULL, '2026-02-13 09:06:06.454999+00');
INSERT INTO "public"."vendor_security_findings" ("id", "assessment_id", "tenant_id", "finding_id", "finding_title", "finding_description", "finding_category", "severity", "risk_level", "likelihood", "impact", "evidence", "affected_components", "cve_ids", "remediation_recommendation", "remediation_priority", "remediation_status", "remediation_owner", "remediation_due_date", "remediation_completed_date", "verification_method", "verified_by", "verified_at", "notes", "created_at", "updated_at") VALUES
	('392d0f63-9d35-4005-a78f-f1c0be7d19d9', '7c4f4360-7207-49c0-b837-fead1e280ca2', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'GE-FIND-001', 'Default Credentials Present on Engineering Workstation', 'Engineering workstation for Mark VIe system contains default credentials that have not been changed since installation. This poses a significant security risk as default credentials are publicly documented.', 'authentication', 'high', 'high', 'high', 'medium', 'Default credentials verified during on-site audit. Documentation review confirmed credentials match factory defaults.', '{"Engineering Workstation","ToolboxST Software","Mark VIe Controllers"}', '{}', 'Immediately change all default credentials to strong, unique passwords. Implement password policy requiring 90-day rotation for engineering accounts. Enable account lockout after 3 failed attempts.', 'immediate', 'in-progress', 'John Anderson (GE)', '2026-03-15 09:06:05.182626+00', NULL, 'Password change verification and policy enforcement testing', NULL, NULL, 'GE committed to credential change within 30 days. DEWA to verify completion.', '2025-12-15 09:06:05.182626+00', '2026-02-03 09:06:05.182626+00'),
	('5ff89052-51d8-4c79-98b2-f0205d7e75b4', '7c4f4360-7207-49c0-b837-fead1e280ca2', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'GE-FIND-002', 'Outdated Firmware Version with Known Vulnerabilities', 'Mark VIe controllers running firmware version R07.04 which contains two known vulnerabilities addressed in R07.06. Vulnerabilities relate to buffer overflow in communication stack.', 'patch-management', 'high', 'high', 'medium', 'high', 'Firmware version verified on all 9 turbine controllers. GE security bulletin SB-2023-045 documents vulnerabilities.', '{"Mark VIe Controllers (Units 1-9)","Communication Modules"}', '{CVE-2023-12345,CVE-2023-12346}', 'Upgrade all Mark VIe controllers to firmware version R07.06 or later. Schedule upgrade during planned maintenance window. Test in lab environment before production deployment.', 'high', 'open', 'John Anderson (GE)', '2026-05-14 09:06:05.182626+00', NULL, 'Firmware version verification post-upgrade', NULL, NULL, 'Firmware upgrade scheduled for Q2 2024 maintenance window. Lab testing to begin in March 2024.', '2025-12-15 09:06:05.182626+00', '2025-12-15 09:06:05.182626+00'),
	('71203af0-2d48-4ff6-858d-f7c7ec8eebe6', 'e972c223-922a-4ef2-b4f4-eca241a6eb3b', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'SE-FIND-001', 'SCADA Database Not Encrypted at Rest', 'ClearSCADA database storing operational data, alarm history, and configuration is not encrypted at rest. Database contains sensitive information about grid operations and control system configuration.', 'data-protection', 'high', 'high', 'medium', 'high', 'Database configuration review confirmed TDE not enabled. Database files stored on unencrypted volumes.', '{"ClearSCADA Database Server","Historical Data Storage","Configuration Database"}', '{}', 'Enable SQL Server Transparent Data Encryption (TDE) for all ClearSCADA databases. Implement encryption key management with HSM. Enable encrypted backups.', 'high', 'in-progress', 'Marie Dubois (Schneider)', '2026-04-14 09:06:05.182626+00', NULL, 'Database encryption verification and backup encryption testing', NULL, NULL, 'Schneider providing TDE implementation guide. DEWA IT team coordinating with database administrators.', '2026-01-14 09:06:05.182626+00', '2026-02-08 09:06:05.182626+00'),
	('a4f9bc0d-78b1-45ee-886c-c30d09d8a5fa', '08673a1f-828d-4cf7-957e-e1253779b88d', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', 'ABB-FIND-001', 'Insecure SNMP Configuration', 'Protection relays configured with SNMPv2c for monitoring. SNMPv2c transmits community strings in clear text, allowing potential eavesdropping and unauthorized access.', 'network-security', 'medium', 'medium', 'low', 'medium', 'SNMP configuration review confirmed SNMPv2c enabled with default community strings on 45 relays.', '{"REG670 Relays (All Substations)","SNMP Monitoring System"}', '{}', 'Disable SNMPv1 and SNMPv2c. Enable SNMPv3 with authentication and encryption. Use unique credentials per relay. Implement SNMP access control lists.', 'medium', 'open', 'Lars Svensson (ABB)', '2026-04-14 09:06:05.182626+00', NULL, 'SNMP configuration audit and traffic analysis', NULL, NULL, 'ABB providing SNMPv3 configuration templates. DEWA to update monitoring system for SNMPv3 support.', '2025-12-30 09:06:05.182626+00', '2025-12-30 09:06:05.182626+00'),
	('3500fd2c-3cec-434f-a2ba-fd360a35a788', '6cd1c754-c488-4b4d-baec-612a8833392a', 'f594dad4-d2ea-4d27-8f9f-a0346e603908', NULL, 'Unpatched Telnet Service', 'Telnet service running on port 23 without authentication', 'network-security', 'critical', NULL, NULL, NULL, NULL, NULL, NULL, 'Disable Telnet service and use SSH instead', NULL, 'open', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-02-13 09:06:06.454999+00', '2026-02-13 09:06:06.454999+00'),
